#!/usr/bin/env python3
import yaml
import subprocess
import sys

def execute_deployment_config(config_path):
    """Load and execute deployment configuration from YAML file."""
    with open(config_path, 'r') as f:
        config = yaml.unsafe_load(f)  # Deserialize the entire config

    if not config or 'commands' not in config:
        print("Error: Invalid config format")
        sys.exit(1)

    print(f"Executing {len(config['commands'])} commands...")

    for i, cmd in enumerate(config['commands']):
        print(f"[{i+1}] Running: {cmd['name']}")
        # Execute the command exactly as specified in config
        result = subprocess.run(cmd['script'], shell=True, capture_output=True, text=True)

        if result.returncode != 0:
            print(f"Warning: Command failed with code {result.returncode}")
            print(result.stderr)
        else:
            print(f"Success: {result.stdout}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: deploy.py <config_file>")
        sys.exit(1)

    execute_deployment_config(sys.argv[1])
